package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.domain.RunRecord;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** 单一运行marker的实际Mapper兼容证明；旧NULL不回填、不重写已存哈希。 */
class RunJsonCodecPersistenceTest extends StaticQuestionAnswerTestFixture {
    private long pureVersion(){var raw=canvas();raw.getJSONArray("nodes").remove(1);data(raw,"node-start::s").getJSONObject("nodeParam").put("opaqueNull",null);data(raw,"node-end::e").put("inputs",new JSONArray());raw.put("edges",new JSONArray(java.util.List.of(JSONObject.of("source","node-start::s","target","node-end::e"))));return version(raw);}
    private JSONObject pureTask(){var task=task(pureVersion());leases.beginExecution(task.getString("runId"),worker,task.getString("leaseId"),task.getIntValue("attempt"));return task;}
    private JSONObject pureEvent(JSONObject task,JSONObject payload){var value=event(task,payload);value.put("nodeId","node-start::s");return value;}
    private void legacy(JSONObject task)throws Exception{assertEquals(1,sql("UPDATE paiflow_run SET run_json_codec=NULL WHERE id='"+task.getString("runId")+"'"));assertNull(runMapper.find(task.getString("runId")).getRunJsonCodec());}
    @Test void oldNullRequestHashReplaysOriginalMissingAndExplicitNullEquivalence() throws Exception {
        long v=pureVersion();var missing=new JSONObject();var view=runs.create(v,"python",missing,"old_null_codec_request",300);var request=JSONObject.of("workflowVersionId",v,"engineProfile","python","input",missing,"timeoutSeconds",300);assertEquals(1,sql("UPDATE paiflow_run SET run_json_codec=NULL,input_hash='"+RunJsonBoundary.hash(request)+"' WHERE id='"+view.runId()+"'"));String oldHash=runMapper.find(view.runId()).getInputHash();
        assertEquals(view.runId(),runs.create(v,"python",JSONObject.of("extra",null),"old_null_codec_request",300).runId());assertNull(runMapper.find(view.runId()).getRunJsonCodec());assertEquals(oldHash,runMapper.find(view.runId()).getInputHash());assertEquals(1,rows("paiflow_run"));
    }
    @Test void newV2RequestDistinguishesMissingAndExplicitNullWithNoSecondRun() throws Exception {long v=pureVersion();var view=runs.create(v,"python",new JSONObject(),"new_v2_codec_request",300);assertEquals(RunJsonCodec.V2,runMapper.find(view.runId()).getRunJsonCodec());assertEquals(409,denied(()->runs.create(v,"python",JSONObject.of("extra",null),"new_v2_codec_request",300)));assertEquals(1,rows("paiflow_run"));}
    @Test void explicitV1MarkerKeepsLegacyRequestEventAndResultReplays() throws Exception {
        long v=pureVersion();var input=JSONObject.of("question","本地实际题面");String key="explicit_v1_request_key";var view=runs.create(v,"python",input,key,300);var request=JSONObject.of("workflowVersionId",v,"engineProfile","python","input",input,"timeoutSeconds",300);assertEquals(1,sql("UPDATE paiflow_run SET run_json_codec='"+RunJsonCodec.V1+"',input_hash='"+RunJsonBoundary.hash(request)+"' WHERE id='"+view.runId()+"'"));var withNull=copy(input);withNull.put("extra",null);assertEquals(view.runId(),runs.create(v,"python",withNull,key,300).runId());var task=leases.claim(worker);leases.beginExecution(view.runId(),worker,task.getString("leaseId"),task.getIntValue("attempt"));var e=pureEvent(task,JSONObject.of("opaque",null));leases.append(view.runId(),worker,e);e.put("payload",new JSONObject());assertTrue(leases.append(view.runId(),worker,e).getBooleanValue("accepted"));leases.result(view.runId(),worker,result(task,"COMPLETED",JSONObject.of("opaque",null)));assertTrue(leases.result(view.runId(),worker,result(task,"COMPLETED",new JSONObject())).getBooleanValue("accepted"));assertEquals(RunJsonCodec.V1,runMapper.find(view.runId()).getRunJsonCodec());assertEquals(1,rows("paiflow_run"));assertEquals(2,rows("paiflow_run_event"));
    }
    @Test void everyPureAssignmentRetainsExecutionNullAndOriginalCanonicalBytes() throws Exception {var task=pureTask();var p=data(task.getJSONObject("dsl"),"node-start::s").getJSONObject("nodeParam");assertTrue(p.containsKey("opaqueNull"));assertNull(p.get("opaqueNull"));var bytes=Base64.getDecoder().decode(task.getString("dslCanonicalBase64"));assertEquals(task.get("dsl"),JSON.parseObject(new String(bytes,StandardCharsets.UTF_8)));assertEquals(task.get("dslHash"),java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)));assertTrue(data(JSON.parseObject(runMapper.find(task.getString("runId")).getAssignmentJson()).getJSONObject("dsl"),"node-start::s").getJSONObject("nodeParam").containsKey("opaqueNull"));}
    @Test void oldNullEventReplayKeepsLegacyBytesAndOriginalEquivalence() throws Exception {var task=pureTask();legacy(task);var first=pureEvent(task,JSONObject.of("opaque",null));leases.append(task.getString("runId"),worker,first);String saved=runMapper.event(task.getString("runId"),1);assertEquals(RunJsonBoundary.canonical(first),saved);assertFalse(JSON.parseObject(saved).getJSONObject("payload").containsKey("opaque"));var missing=copy(first);missing.put("payload",new JSONObject());assertTrue(leases.append(task.getString("runId"),worker,missing).getBooleanValue("accepted"));assertEquals(saved,runMapper.event(task.getString("runId"),1));assertEquals(1,rows("paiflow_run_event"));}
    @Test void newV2EventPreservesNullAndRejectsMissingReplay() throws Exception {var task=pureTask();var first=pureEvent(task,JSONObject.of("opaque",null));leases.append(task.getString("runId"),worker,first);var stored=JSON.parseObject(runMapper.event(task.getString("runId"),1));assertTrue(stored.getJSONObject("payload").containsKey("opaque"));assertNull(stored.getJSONObject("payload").get("opaque"));var missing=copy(first);missing.put("payload",new JSONObject());assertEquals(409,denied(()->leases.append(task.getString("runId"),worker,missing)));assertEquals(stored,runs.events(task.getString("runId"),0,10).get(0));assertEquals(1,rows("paiflow_run_event"));}
    @Test void oldNullResultReplayKeepsHashAndLegacyStoredJson() throws Exception {var task=pureTask();legacy(task);var first=result(task,"COMPLETED",JSONObject.of("opaque",null));leases.result(task.getString("runId"),worker,first);String hash=runMapper.find(task.getString("runId")).getResultHash(),saved=runMapper.find(task.getString("runId")).getResultJson();assertEquals(RunJsonBoundary.hash(first),hash);assertEquals(RunJsonBoundary.canonical(first),saved);assertTrue(leases.result(task.getString("runId"),worker,result(task,"COMPLETED",new JSONObject())).getBooleanValue("accepted"));assertEquals(saved,runMapper.find(task.getString("runId")).getResultJson());assertEquals(hash,runMapper.find(task.getString("runId")).getResultHash());assertNull(runMapper.find(task.getString("runId")).getRunJsonCodec());}
    @Test void newV2ResultPreservesNullAndRejectsMissingReceipt() throws Exception {var task=pureTask();var first=result(task,"COMPLETED",JSONObject.of("opaque",null));leases.result(task.getString("runId"),worker,first);var stored=JSON.parseObject(runMapper.find(task.getString("runId")).getResultJson());assertTrue(stored.getJSONObject("output").containsKey("opaque"));assertNull(stored.getJSONObject("output").get("opaque"));assertEquals(RunJsonBoundary.hashFull(first),runMapper.find(task.getString("runId")).getResultHash());assertEquals(409,denied(()->leases.result(task.getString("runId"),worker,result(task,"COMPLETED",new JSONObject()))));assertEquals(stored,runs.detail(task.getString("runId")).result());assertEquals(1,rows("paiflow_run_event"));}
    @Test void runUpdateNeverChangesImmutableCodecAndUnknownCodecHasNoFallback() throws Exception {var task=pureTask();var row=runMapper.find(task.getString("runId"));long revision=row.getRevision();row.setRunJsonCodec(RunJsonCodec.V1);assertEquals(1,runMapper.update(row));assertEquals(RunJsonCodec.V2,runMapper.find(row.getId()).getRunJsonCodec());assertEquals(revision+1,runMapper.find(row.getId()).getRevision());var unknown=new RunRecord();unknown.setRunJsonCodec("future");assertEquals(409,denied(()->RunJsonCodec.canonical(unknown,new JSONObject())));assertEquals(409,denied(()->RunJsonCodec.hash(unknown,new JSONObject())));}
    @Test void queuedCancellationAndCenterExpiryUseRunMarkerWithoutRewritingHistory() throws Exception {long v=pureVersion();var queued=runs.create(v,"python",new JSONObject(),"queued_cancel_codec_key",300);runs.cancel(queued.runId());assertEquals("CANCELLED",runMapper.find(queued.runId()).getState());assertEquals(RunJsonCodec.V2,runMapper.find(queued.runId()).getRunJsonCodec());var task=pureTask();legacy(task);clock.value=clock.value.plusSeconds(61);assertEquals(1,leases.reconcileExpiredRuns());var expired=runMapper.find(task.getString("runId"));assertEquals("FAILED",expired.getState());assertNull(expired.getRunJsonCodec());assertEquals(RunJsonBoundary.hash(JSON.parseObject(expired.getResultJson())),expired.getResultHash());assertEquals(RunJsonBoundary.canonical(JSON.parseObject(expired.getResultJson())),expired.getResultJson());}
    @Test void unknownFutureMarkerIsRejectedAcrossUserWorkerAndCheckpointPaths() throws Exception {
        var task=begun(canvas());var cp=checkpoint(task);
        // 只在随机H2模拟未来数据库版本的记录；正式017 CHECK仍保全，生产Service必须拒未知值。
        try(var connection=db.getConnection();var statement=connection.createStatement()){statement.execute("ALTER TABLE paiflow_run DROP CONSTRAINT ck_paiflow_run_json_codec");}
        assertEquals(1,sql("UPDATE paiflow_run SET run_json_codec='future' WHERE id='"+task.getString("runId")+"'"));
        assertEquals(409,denied(()->runs.detail(task.getString("runId"))));assertEquals(409,denied(()->runs.cancel(task.getString("runId"))));assertEquals(409,denied(()->leases.verify(task.getString("runId"),worker,task.getString("leaseId"),task.getIntValue("attempt"))));assertEquals(409,denied(()->reply(task,cp,"resume","未知codec")));assertEquals("WAITING",checkpointMapper.find(cp.getString("checkpointId")).getState());clock.value=clock.value.plusSeconds(61);assertEquals(409,denied(checkpoints::reconcileEnded));assertEquals("WAITING",checkpointMapper.find(cp.getString("checkpointId")).getState());assertNull(runMapper.find(task.getString("runId")).getResultJson());assertEquals(0,rows("paiflow_run_event"));
    }

}
